$ErrorActionPreference = "Stop"
$repoRoot = Split-Path -Parent $PSScriptRoot

function Read-RepoFile([string] $relativePath) {
    return Get-Content -LiteralPath (Join-Path $repoRoot $relativePath) -Raw
}

function Assert-True([bool] $condition, [string] $message) {
    if (-not $condition) { throw "FAIL: $message" }
    Write-Output "PASS: $message"
}

$entry = Read-RepoFile "src\Rupture\RupturePlugin.cs"
$entry += Read-RepoFile "src\Rupture\RuptureConfiguration.cs"
$contracts = Read-RepoFile "src\Rupture\Ragdolls\External\ExternalPhysicsContracts.cs"
$loader = Read-RepoFile "src\Rupture\Ragdolls\External\ExternalPhysicsBackendLoader.cs"
$world = Read-RepoFile "src\Rupture\Ragdolls\Classes\ShadowRagdollWorld.cs"
$runtime = Read-RepoFile "src\Rupture.PhysXBackend\ExternalPhysXRuntime.cs"
$runtime += Read-RepoFile "src/Rupture.PhysXBackend/ExternalPhysicsHandles.cs"
$hierarchyFilter = Read-RepoFile "src/Rupture.PhysXBackend/EnvironmentHierarchyFilter.cs"
$nativeScene = Read-RepoFile "src\Rupture.PhysXBackend\NativeScene.cs"
$mesh = Read-RepoFile "src\Rupture.PhysXBackend\MeshGeometry.cs"
$meshSources = Read-RepoFile "src\Rupture.PhysXBackend\MeshGeometrySources.cs"
$nativeApi = Read-RepoFile "src\Rupture.PhysXBackend\NativeApi.cs"
$backendManifest = Read-RepoFile "src\Rupture.PhysXBackend\physx-backend.json"
$nativeHeader = Read-RepoFile "src\Rupture.PhysX.Native\include\rpt_physx_bridge.h"
$nativeBridge = Read-RepoFile "src\Rupture.PhysX.Native\src\rpt_physx_bridge.cpp"
$killPatch = Read-RepoFile "src\Rupture\Combined\Patches\KillPatch.cs"
$grenade = Read-RepoFile "src\Rupture\Ragdolls\Classes\GrenadePhysics.cs"
$limbs = Read-RepoFile "src\Rupture\Dismemberment\Classes\Limbs\LimbDismembermentSystem.cs"
$limbs += Read-RepoFile "src/Rupture/Dismemberment/Classes/Limbs/LimbDismembermentSystem.Worker.cs"
$limbs += Read-RepoFile "src/Rupture/Dismemberment/Classes/Limbs/LimbDismembermentSystem.Decals.cs"
$shotImpact = Read-RepoFile "src\Rupture\Ragdolls\Classes\ShotImpactProcessor.cs"
$package = Read-RepoFile "scripts\Build-Package.ps1"
$weaponState = [regex]::Match($world, 'private static void UpdateIndependentWeaponState\(ShadowRig rig\)[\s\S]*?(?=\r?\n\tprivate static void SyncDetachedEffectsFromProxy)').Value
$bodyCapture = [regex]::Match($nativeScene, 'internal static ActorSnapshot CaptureBody\([\s\S]*?(?=\r?\n\tinternal static ActorSnapshot CaptureTransientConvexBody)').Value

Assert-True ($bodyCapture -match 'Flags = 1u' -and $bodyCapture -notmatch 'body\.collisionDetectionMode' -and $nativeApi -match 'SceneFlags = source.SceneFlags \| \(1u << 1\)') "external corpse actors and scene always enable swept CCD independently of EFT authority discrete collision mode"

Assert-True ($contracts -match 'ProximityCache' -and $contracts -match 'PrebakeEntireRaid' -and $contracts -notmatch 'UnityPhysicsScene|ShadowPhysicsBackendMode') "external environment policies remain backend-neutral while the obsolete backend selector is absent"
Assert-True ($entry -match '"External Environment Mode",\s*ExternalEnvironmentMode\.ProximityCache' -and $entry -match '"External PhysX Dispatcher Threads",\s*2' -and $entry -match 'AcceptableValueRange<int>\(0,\s*4\)' -and $entry -notmatch '"Shadow Physics Backend"|"External Mesh Extraction"') "external PhysX with Unity-owned extraction is the sole production path"
Assert-True ($runtime -match 'new UnityPhysXMeshGeometrySource' -and $runtime -notmatch 'GpuInstanceMeshGeometrySource' -and $meshSources -notmatch 'GpuInstanceMeshGeometrySource') "GPU-buffer extraction is removed from the backend"
Assert-True ($loader -match 'WoundResources.PluginRoot' -and $loader -match 'Assembly\.LoadFrom\(managedPath\)' -and $nativeApi -match 'LoadLibraryExW\(libraryPath' -and $nativeApi -match 'GetProcAddress\(_module') "managed and native backends load explicitly from the Rupture directory"
Assert-True ($nativeApi -match 'AbiVersion\s*=\s*10' -and $nativeHeader -match 'RPTPX_ABI_VERSION\s*=\s*10' -and $backendManifest -match '"abiVersion"\s*:\s*10') "managed, native, and package metadata agree on graphical casing ABI 10"
Assert-True ($runtime -match '_stableSceneFrames\s*>=\s*2' -and $runtime -match 'GetComponentsInChildren<Collider>\(true\)' -and $runtime -match 'NativeScene staging' -and $runtime -match 'full bake committed atomically') "full prebake waits for stable scenes, includes inactive objects, and commits a staging scene atomically"
Assert-True ($mesh -notmatch 'GetVertexBuffer\(|GetIndexBuffer\(|AsyncGPUReadback|GraphicsBuffer\.GetData') "production mesh geometry contains no GPU-buffer extraction path"
Assert-True ($mesh -match 'HashGeometry\(' -and $mesh -match 'baked-signed-scale' -and $runtime -match 'MeshGeometryRepository\.Clear\(\)') "raw geometry is revalidated per raid and signed-scale baking participates in cache identity"
Assert-True ($meshSources -match 'ContactModifyEvent' -and $meshSources -match 'ResolveShapeToCollider' -and $meshSources -match 'ExtractUnityMesh' -and $nativeBridge -match 'rptpx_unity_enumerate_shapes' -and $nativeBridge -match 'rptpx_unity_overlap_shapes' -and $nativeBridge -match 'getTriangleMeshGeometry' -and $nativeBridge -match 'getConvexMeshGeometry') "Unity extraction bootstraps, proximity-maps, and copies post-cook triangle and convex topology"
Assert-True ($meshSources -match 'PrepareProximity' -and $runtime -match 'PrepareProximity\(center,\s*sweepEnd,\s*EnvironmentRadius' -and $nativeBridge -match 'PxCapsuleGeometry' -and $nativeBridge -match 'PxSphereGeometry' -and $nativeBridge -match 'PxQueryFlag::eSTATIC\s*\|\s*PxQueryFlag::eDYNAMIC' -and $runtime -notmatch '\.isStatic') "ordinary proximity extraction resolves only intersecting Unity PhysX shapes and does not trust EFT GameObject static flags"
Assert-True ($runtime -match 'TerrainCollider' -and $runtime -match 'MeshGeometryRepository\.Get\(\(TerrainCollider\)collider\)' -and $nativeScene -match 'geometry\s*=\s*6' -and $meshSources -match 'ExtractUnityHeightField' -and $nativeBridge -match 'getHeightFieldGeometry' -and $nativeBridge -match 'saveCells' -and $nativeBridge -match 'createHeightField' -and $nativeBridge -match 'PxHeightFieldGeometry') "TerrainCollider is eligible and preserves native PhysX heightfield samples, scaling, pose, holes, and resources"
Assert-True ($nativeBridge -match 'getNbMaterials' -and $nativeBridge -match 'getMaterials' -and $nativeBridge -match 'rptpx_attach_shape_materials' -and $nativeScene -match 'AttachShapeMaterials') "heightfield material indices retain their complete PhysX material table"
Assert-True ($meshSources -match 'ProbeSlowWarningFixedSeconds' -and $meshSources -match 'Time\.fixedTime' -and $meshSources -match 'PulseProbeAfterFixedStep' -and $meshSources -notmatch 'ProbeTimeoutFixedSeconds|ProbeTimeoutFrames|produced no default-scene contact') "Unity extraction bootstrap keeps waiting after a non-fatal slow warning instead of disabling a raid on a timing-dependent deadline"
Assert-True ($meshSources -match 'bootstrap pending:' -and $meshSources -match 'callbacks=' -and $meshSources -match 'MaximumProbeDiagnostics' -and $meshSources -match 'simulationMode=' -and $meshSources -match 'invokeCallbacks=') "Unity extraction bootstrap emits bounded diagnostics that separate missing physics steps, contact callbacks, and Unity callback state"
Assert-True ($meshSources -match 'ContactModifyEventCCD \+= OnContactModify' -and $meshSources -match 'CollisionDetectionMode\.Discrete' -and $meshSources -match 'providesContacts\s*=\s*true' -and $meshSources -notmatch 'Vector3\.up \* 100f') "Unity extraction listens to both contact channels and explicitly requests contacts inside the active raid broadphase"
Assert-True ($meshSources -match '__RPT_UnityPhysXGeometryProbe_Stationary' -and $meshSources -match '__RPT_UnityPhysXGeometryProbe_Dynamic' -and $meshSources -match 'overlapStep' -and $meshSources -match 'Physics\.IgnoreCollision\(_probeStationaryCollider, _probeDynamicCollider, false\)' -and $meshSources -match 'DestroyProbe\(\)') "Unity extraction uses distinct actors, repeatedly recreates its contact pair, and removes the probe after bootstrap"
Assert-True ($meshSources -match 'IgnoreNearbyEnvironmentColliders' -and $meshSources -match 'Physics\.ComputePenetration' -and $meshSources -match 'pair=\{ProbeOverlapStatus\(\)\}') "Unity extraction isolates the in-bounds probe from gameplay colliders and reports whether its own pair overlaps"
Assert-True ($nativeScene -match '_source\.Read\(collider\)' -and $runtime -match 'DeferredUnityShapeAuditPerFrame' -and $runtime -match 'deferred-unity-shape') "Unity-owned extraction feeds the geometry repository and inactive mesh or terrain shapes are added lazily"
Assert-True ($runtime -match 'attachedRigidbody' -and $runtime -match 'Animator' -and $runtime -match 'integrity audit promotes any other root' -and $runtime -match 'SetActorPose' -and $runtime -match 'ReplaceActorShapes' -and $runtime -match 'SetShapeEnabled') "rigidbody, explicit transform-driven, and audited moving actors propagate pose, scale, and enable-state changes"
Assert-True ($runtime -notmatch 'hierarchyNotStatic' -and $runtime -match '_bodyShapesByCollider\.ContainsKey\(colliderId\)' -and $runtime -match '_environmentHierarchy.Allows\(collider.transform\)' -and $hierarchyFilter -match 'component is ParticleSystem' -and $hierarchyFilter -match 'EFT.Player' -and $hierarchyFilter -match 'EFT.Interactive.Corpse') "baked floors remain static and runtime census excludes body-owned and particle-effect colliders"
Assert-True ($nativeScene -match 'worldFrameRotation\s*=\s*joint\.transform\.rotation\s*\*\s*childFrameRotation' -and $nativeScene -match 'Quaternion\.Inverse\(joint\.connectedBody\.rotation\)\s*\*\s*worldFrameRotation') "character-joint child and connected frames share the same initial world orientation"
Assert-True ($nativeScene -notmatch 'NativeJointReferencePose|referenceRotation \* childFrameRotation' -and $world -notmatch 'NativeJointReferencePose') "the regressed creation-time joint frame override is absent"
Assert-True ($world -match 'rig.ExternalGroup <= 4' -and $world -match 'JointDiagnosticSamples = 3' -and $world -match 'maxAnchorGapMm' -and $world -match 'admissionDeltaDeg') "head joint and anchor separation diagnostics are bounded to four rigs and three samples"
Assert-True ($nativeBridge -match 'rptpx_unity_get_scene_settings' -and $nativeBridge -match 'settings->solver_type\s*=\s*static_cast<uint32_t>\(PxSolverType::ePGS\)' -and $nativeBridge -match 'getFrictionType\(\)' -and $nativeBridge -match 'getFlags\(\)' -and $meshSources -match 'SourceSceneSettings' -and $runtime -match 'source parity') "the external scene waits for the version-gated Unity source solver plus live friction and contact-solver flags"
Assert-True ($nativeBridge -match 'scene_desc\.solverType\s*=\s*static_cast<PxSolverType::Enum>\(desc->solver_type\)' -and $nativeBridge -match 'scene_desc\.frictionType\s*=\s*static_cast<PxFrictionType::Enum>\(desc->friction_type\)' -and $nativeBridge -match 'copy_source_scene_flags\(scene_desc\.flags,\s*desc->scene_flags\)' -and $nativeBridge -notmatch 'solverType\s*=\s*PxSolverType::eTGS') "external PhysX applies source scene solver, friction, and relevant flags instead of forcing TGS"
Assert-True ($nativeBridge -match 'eENABLE_CCD' -and $nativeBridge -match 'eDETECT_CCD_CONTACT') "CCD symbols are wired; executable thin-wall and handoff regressions run in the native suite"
Assert-True ($nativeScene -match 'SolverPositionIterations\s*=\s*\(uint\)body\.solverIterations' -and $nativeScene -match 'SolverVelocityIterations\s*=\s*\(uint\)body\.solverVelocityIterations' -and $nativeScene -notmatch 'Math\.Max\((8|2),\s*body\.solver') "external bodies preserve each Unity Rigidbody solver iteration count exactly"
Assert-True ($nativeBridge -match 'was_kinematic\s*!=\s*will_be_kinematic' -and $nativeBridge -match 'clearForce\(PxForceMode::eFORCE\)' -and $nativeBridge -match 'clearForce\(PxForceMode::eIMPULSE\)' -and $nativeBridge -match 'clearTorque\(PxForceMode::eIMPULSE\)') "dynamic and kinematic ownership transitions defensively discard interrupted force and impulse accumulators"
Assert-True ($world -match 'foreach \(Collider corpseCollider in corpseBody\.NativeColliders\)' -and $world -match '_externalRuntime\.IgnoreCollision\(effectCollider,\s*corpseCollider\)' -and $world -match 'native\.position\s*=\s*simulation\.position' -and $world -match 'native\.rotation\s*=\s*simulation\.rotation' -and $killPatch -notmatch 'colliderForce') "external gore is presented and excluded from its source corpse while the retired arterial-particle collider-force hook stays absent"
Assert-True ($contracts -match 'EnvironmentOnly\s*=\s*1' -and $world -match 'RegisterLocalDetachedGib' -and $world -match 'NetworkPoseEligible\s*=\s*!localEnvironmentOnly' -and $world -match 'ConfigureLocalGibQueryCollider' -and $world -match 'excludeLayers\s*=\s*new LayerMask \{ value = ~0 \}' -and $nativeScene -match 'collisionProfile\s*==\s*ExternalCollisionProfile\.DeadbodyAndEnvironment') "procedural limb gibs keep query-only Unity meshes, environment-only external contacts, and no Fika motion snapshots"
Assert-True ($contracts -match 'ExternalTransientConvexShape' -and $contracts -match 'IExternalBodyCreation' -and $contracts -match 'WorkerMilliseconds' -and $contracts -match 'BeginCreateTransientConvexBody' -and $runtime -match 'OwnerWork work = new OwnerWork' -and $runtime -match 'Work\.Completion\.Task\.IsCompleted' -and $runtime -notmatch 'BeginCreateTransientConvexBody[\s\S]{0,2600}Task\.Wait') "transient convex bodies are created, timed, and polled without synchronously waiting on the owner thread"
Assert-True ($limbs -match 'PendingExternalShapes' -and $limbs -match 'generatedShapes\.Add\(new ExternalTransientConvexShape' -and $world -match 'transientShapes == null \|\| transientShapes\.Length == 0' -and $world -notmatch 'TryCaptureTransientConvexShapes') "validated gib proxy arrays pass directly into external PhysX without Unity mesh re-extraction"
Assert-True ($nativeScene -match 'TransientMesh' -and $nativeScene -match 'rptpx_create_transient_mesh_from_cooked' -and $nativeScene -match '_transientMeshesByActor' -and $nativeScene -notmatch 'if \(transient\)[\s\S]{0,700}File\.WriteAllBytes' -and $nativeApi -match 'rptpx_destroy_mesh' -and $nativeHeader -match 'rptpx_destroy_mesh') "transient gib meshes bypass persistent cache files and release native mesh handles with their actor"
Assert-True ($runtime -match 'NotifySceneLoaded' -and $runtime -match 'late-scene' -and $runtime -match 'runtime-proximity' -and $runtime -match 'AuditStaticActors' -and $runtime -match 'TryPromoteStaticActor' -and $runtime -match 'CaptureEnvironment\(actor\.Root,\s*colliders,\s*movable:\s*true' -and $nativeScene -match 'ReplaceNative') "late scenes, runtime-spawn safety discovery, and moved-static to kinematic promotion are present"
Assert-True ($runtime -match 'EnvironmentShapeAuditPerFrame\s*=\s*64' -and $runtime -match 'StaticAuditPerFrame\s*=\s*16' -and $runtime -match '_movableEnvironmentActors' -and $runtime -match 'AuditEnvironmentShapes\(\)' -and $runtime -notmatch 'RuntimeCensusIntervalFrames' -and $runtime -notmatch '_nextRuntimeCensusFrame') "steady-state environment maintenance audits bounded slices and directly visits only registered movable actors"
Assert-True ($runtime -notmatch 'name\.IndexOf\("Interactive"' -and $runtime -match 'name\.IndexOf\("Door"' -and $runtime -match 'generic[\s\r\n]+// Interactive components') "generic interactive ancestors cannot classify fixed map geometry as per-frame movable while known doors remain explicit"
Assert-True ($runtime -match 'runtime-proximity' -and $world -match 'FullPrebakeRuntimeProbeIntervalFrames\s*=\s*60' -and $world -match 'NextEnvironmentRefreshFrame') "full prebake discovers runtime-spawned colliders through staggered local safety probes"
Assert-True ($world -match 'CenterBody' -and $world -match 'centerBody\.Proxy\.TransformPoint' -and $world -match 'MaximumProximityAcquiresPerFrame\s*=\s*2' -and $world -match '_environmentRefreshCursor' -and $runtime -match '_proximityUnknownScratch') "active Update uses a representative cached pose, fair bounded proximity work, and reusable query collections"
Assert-True ($world -match 'DetachWeaponFromCorpse' -and $world -notmatch 'ProxyWeaponJoint|SyncWeaponJointState|TryCopyWeaponJoint' -and $world -match 'CountAwakeIndependentBodies' -and $weaponState -notmatch 'isKinematic\s*=\s*true') "weapons remain independent naturally sleeping dynamic bodies after the corpse-hand joint is destroyed"
Assert-True ($contracts -match 'ExternalRoundedBoxShape' -and $contracts -match 'TryCreateRoundedBoxBody' -and $runtime -match 'ActorSnapshot\.CaptureRoundedBoxBody' -and $mesh -match 'CreateWeaponRoundedBox' -and $mesh -match 'WeaponRoundedBoxArcSegments\s*=\s*3' -and $mesh -match 'WeaponRoundedBoxRadiusFractionOfHalfThickness\s*=\s*0\.8f' -and $mesh -notmatch 'ReadWeaponConvex|BakeMesh' -and $world -notmatch 'TryBuildWeaponConvex' -and $world -match 'procedural rounded-box cooking failed; using the fitted box fallback') "weapon shadows use a tiny bounds-only spherobox with broad flat faces and fully rounded edges without attachment mesh readback"
Assert-True ($world -match 'WeaponColliderGeometry.TryFit' -and $world -notmatch 'CollectWeaponRendererBounds|EncapsulateWorldBounds') "weapon fitting uses native local collider geometry independently of render state and world AABBs"
Assert-True ($shotImpact -match 'independentWeaponHit[\s\S]{0,180}PrepareCorpseImpact' -and $shotImpact -match 'TryApplyIndependentWeaponPointImpulse' -and $world -match 'ReferenceEquals\(body,\s*rig\.WeaponBody\)' -and $world -match 'TryWakeIndependentWeapon') "direct weapon hits wake and impulse the independent weapon without activating its parent corpse"
Assert-True ($nativeScene -match 'TwistStiffness' -and $nativeScene -match 'SwingStiffness' -and $nativeScene -match 'TwistContactDistance' -and $nativeBridge -match 'swing_y_limited' -and $nativeBridge -match 'PxD6Motion::eLOCKED') "external character joints preserve separate limit parameters and lock zero-width angular axes"
Assert-True ($nativeScene -match 'Projection\s*=\s*source\.enableProjection\s*\?\s*1u\s*:\s*0u' -and $nativeScene -match 'ProjectionLinearTolerance\s*=\s*source\.projectionDistance' -and $nativeScene -match 'ProjectionAngularTolerance\s*=\s*source\.projectionAngle\s*\*\s*Mathf\.Deg2Rad' -and $nativeScene -notmatch 'source\.enableProjection\s*\?\s*Mathf\.Max') "external character joints preserve Unity projection enablement and tolerances without synthetic fallbacks"
Assert-True ($world -match 'TryWakeIndependentWeapon' -and $world -match 'independentWeaponLifecycle=' -and $world -match '!HasDynamicIndependentWeapon\(rig\)[\s\S]{0,80}ReleaseEnvironment\(rig\)' -and $weaponState -notmatch 'ReleaseEnvironment\(rig\)' -and $grenade -match 'ShadowRagdollWorld\.IsSettled') "settled dynamic weapons retain their support corridor through sleep and wake independently from forces, explosions, and moving geometry"
Assert-True ($runtime -match 'TaskCompletionSource<bool>' -and $runtime -match 'an external simulation step is already in flight' -and $world -match 'ExternalStepWatchdogMilliseconds\s*=\s*500' -and $world -match 'MainWaitMilliseconds' -and $world -match 'ExternalMainWaitP99') "one-step signaling, catastrophic watchdog, readiness, and p99 main-wait diagnostics are wired"
Assert-True ($world -match 'if\s*\(!raidSimulationActive\)[\s\S]{0,120}return;' -and $world -match 'if\s*\(!_externalRuntime\.IsRaidReady\)[\s\S]{0,300}return;') "map loading permits prebake but suppresses continuous simulation until both the raid and external scene are ready"
Assert-True ($world -match 'SubmitStep\(deltaTime' -and $world -notmatch '_physicsScene\.Simulate|CreateSceneParameters\(LocalPhysicsMode\.Physics3D\)' -and $world -match 'EFT native corpse physics remains active') "RPT never steps a Unity shadow PhysicsScene and fails open to EFT native physics"
Assert-True ($entry -notmatch 'Log Generated Environment Colliders|Dump Generated Environment Colliders|DumpGeometryLookupManifest' -and -not (Test-Path -LiteralPath (Join-Path $repoRoot 'src\Rupture\Ragdolls\Classes\GeneratedEnvironmentColliderDumper.cs'))) "obsolete GPU and local-proxy feasibility diagnostics are absent"
Assert-True ($package.Contains('BepInEx/plugins/rupture') -and $package -match 'PhysXPackageLayout.Tests.ps1' -and (Test-Path -LiteralPath (Join-Path $repoRoot 'tests/PhysXNativeDependencies.Tests.ps1'))) "package construction enforces flat Rupture backend payload"

Write-Output "ALL PASS: external PhysX structural checks; runtime behavior requires executable regressions"
